	docker run -v /mnt/8EEE3D67EE3D492B/Sandoz_terreus/ATSec/trimmed/$base:/reads -v /mnt/8EEE3D67EE3D492B/Sandoz_terreus/NIH_ref/reference:/reference -v /mnt/8EEE3D67EE3D492B/Sandoz_terreus/ATSec/aligned/$base:/output_directory mikischikora/persvade:v1.02.6 python -u  ./scripts/perSVade align_reads -f /reads/trimmed_reads.fastq.gz --ref /reference/GCA_000149615.1_ASM14961v1_genomic.fna -o /output_directory --fraction_available_mem 0.7
	docker run -v /mnt/8EEE3D67EE3D492B/Sandoz_terreus/ATSec/small_vars/$base:/output_directory -v /mnt/8EEE3D67EE3D492B/Sandoz_terreus/NIH_ref/reference:/reference -v /mnt/8EEE3D67EE3D492B/Sandoz_terreus/ATSec/aligned/$base:/aligned -v /mnt/8EEE3D67EE3D492B/Sandoz_terreus/NIH_ref/repeats:/repeats mikischikora/persvade:v1.02.6 python -u  ./scripts/perSVade  call_small_variants -o /output_directory --ref /reference/GCA_000149615.1_ASM14961v1_genomic.fna -p 1 -sbam /aligned/aligned_reads.bam.sorted --repeats_file /repeats/combined_repeats.tab --callers bcftools,freebayes,HaplotypeCaller --min_AF 0.9 --min_coverage 20 --fraction_available_mem 0.7
	docker run -v /mnt/8EEE3D67EE3D492B/Sandoz_terreus/ATSec/small_vars_annotated/$base:/output_directory -v /mnt/8EEE3D67EE3D492B/Sandoz_terreus/NIH_ref/reference:/reference -v /mnt/8EEE3D67EE3D492B/Sandoz_terreus/ATSec/small_vars/$base:/vcf mikischikora/persvade:v1.02.6 python -u  ./scripts/perSVade  annotate_small_vars -o /output_directory --ref /reference/GCA_000149615.1_ASM14961v1_genomic.fna --mitochondrial_chromosome CH981540.1 -gff /reference/genomic.gff -mcode 4 -gcode 1 --merged_vcf /vcf/variants_atLeast3PASS_ploidy2.vcf --fraction_available_mem 0.7
